#!/usr/bin/env node
// Real, running verification of REMEDIATION 1.5: a manifest's on_install is a
// Docker build layer, and nothing executes it at container boot.
//
// It used to run from run-lifecycle.ts as uid 0 with CAP_SYS_ADMIN, /dev/fuse,
// and no Landlock domain — necessarily before one existed, since the
// capability policy is generated by the very next line of the same script. So
// any berth.yml was arbitrary root code execution inside the sandbox meant to
// constrain it.
//
// The fixture's on_install writes to /etc, which no capability this manifest
// could declare would ever permit at runtime. That's the whole trick: the
// proof file's presence dates the execution. If it exists, something ran the
// command with more authority than the app has — correct at build time, a
// vulnerability at boot.
//
// Four assertions, and the third is the one that matters:
//
//   1. the build layer ran it (the proof file is in the image);
//   2. boot didn't (no lifecycle log line, and no install marker — the
//      mechanism is gone, not merely skipped);
//   3. rewriting berth.yml inside a *running* container and restarting does
//      not execute the new on_install. This is half of 1.6's exploit chain
//      (write a manifest through the bind mount, wait for the restart, get
//      root) and it is the property a reader actually cares about;
//   4. the app itself still can't write where on_install could, which is what
//      makes assertion 1 evidence of anything.
//
// Runs anywhere Docker does. Assertion 4 is the only one that would be
// weakened by an unenforcing kernel, and it's reported as informational
// there for the same reason capability-enforcement.mjs does it — see the
// comment at its call site.
import Docker from "dockerode";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { loadManifest } from "@berth/manifest-schema";
import { buildImage, startContainer, stopContainer, restartContainer, createStdioRpcClient } from "../dist/index.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const FIXTURE_DIR = join(__dirname, "fixtures", "on-install-probe");
const TAG = "berth/on-install-probe:test";
const CONTAINER_NAME = "berth-test-on-install";

const PROOF_PATH = "/etc/berth-on-install-proof";
const PAYLOAD_PATH = "/etc/berth-on-install-payload";

const docker = new Docker();
const failures = [];

function check(name, condition, detail) {
  if (condition) {
    console.log(`  PASS: ${name}`);
  } else {
    console.log(`  FAIL: ${name}${detail ? ` — ${detail}` : ""}`);
    failures.push(name);
  }
}

/**
 * One RPC round trip. Used exactly once, and deliberately: `docker attach` is
 * effectively single-use per container (a second client gets no response, as
 * this test found the hard way), and everything else here is a file-existence
 * question that `docker exec` answers without competing for stdin.
 */
async function readPath(container, path) {
  const rpc = await createStdioRpcClient(container, docker);
  try {
    const response = await rpc.call({ id: "1", export: "read_path", input: { path } });
    if (response.error) throw new Error(response.error);
    return response.result;
  } finally {
    rpc.close();
  }
}

async function execCapture(container, cmd) {
  const exec = await container.exec({ Cmd: cmd, AttachStdout: true, AttachStderr: true });
  const stream = await exec.start({});
  const chunks = [];
  await new Promise((resolve, reject) => {
    stream.on("data", (chunk) => chunks.push(chunk));
    stream.on("end", resolve);
    stream.on("error", reject);
  });
  // Docker multiplexes exec output with an 8-byte header per frame; this only
  // needs to spot substrings, so strip non-printables rather than demux.
  return Buffer.concat(chunks).toString("utf-8").replace(/[\x00-\x08\x0b-\x1f]/g, "");
}

const ABSENT = "__BERTH_ABSENT__";

/** Polls until `predicate` holds or the budget runs out. Returns whether it held. */
async function waitFor(predicate, timeoutMs) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    try {
      if (await predicate()) return true;
    } catch {
      // A container mid-restart refuses exec; that's a "not yet", not a failure.
    }
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  return false;
}

/** Contents of a file inside the container, or ABSENT — never an exception, since "not there" is the expected answer half the time. */
async function fileContent(container, path) {
  return (await execCapture(container, ["sh", "-c", `cat ${path} 2>/dev/null || echo ${ABSENT}`])).trim();
}

async function main() {
  const manifest = await loadManifest(join(FIXTURE_DIR, "berth.yml"));

  console.log("Building on-install-probe's production image...");
  await buildImage({ appDir: FIXTURE_DIR, tag: TAG, target: "production", docker });

  console.log("Starting its sandbox...");
  const running = await startContainer({
    image: TAG,
    name: CONTAINER_NAME,
    manifest,
    // Same override Computer.boot({ enforcement: "warn" }) uses (REMEDIATION
    // 0.1): a production image sets BERTH_REQUIRE_ENFORCEMENT=1, and
    // agent-init then refuses to exec at all on a kernel without Landlock —
    // Docker Desktop's linuxkit, where much of this will be run. Nothing here
    // tests Landlock, so relaxing it costs this file nothing and is what lets
    // it run on a Mac as well as in CI. The container is otherwise identical.
    env: { BERTH_REQUIRE_ENFORCEMENT: "0" },
    docker,
  });

  try {
    console.log("\n--- Test 1: on_install ran at build time ---");
    const proof = await readPath(running.container, PROOF_PATH);
    check(
      "the on_install proof file is present in the image",
      proof.exists && proof.content === "build-time-proof",
      `read_path(${PROOF_PATH}) returned ${JSON.stringify(proof)} — the build layer didn't run it`,
    );

    console.log("\n--- Test 2: nothing ran it at boot ---");
    const logs = (await running.container.logs({ stdout: true, stderr: true })).toString("utf-8");
    check(
      "the boot logs contain no on_install execution",
      !logs.includes("running on_install"),
      "run-lifecycle still executes on_install at boot",
    );
    const marker = await fileContent(running.container, "/app/.berth/installed");
    check(
      "no install-marker file is written",
      marker === ABSENT,
      "the marker still exists, so the boot-time run-once mechanism is still there",
    );

    console.log("\n--- Test 3: rewriting berth.yml and restarting does not execute the new on_install ---");
    // Written from inside the container rather than through a bind mount, so
    // this test never touches the repo it runs from. The authority used here
    // (root, via docker exec) is strictly greater than an app's own, which
    // makes the negative result stronger, not weaker: even a writer who can
    // fully control the manifest gets no boot-time execution out of it.
    const payloadManifest = [
      "name: on-install-probe",
      "version: 0.1.0",
      "capabilities: []",
      "exports:",
      "  - name: read_path",
      "    input: { path: string }",
      "    output: { exists: boolean, content: string }",
      "on_install:",
      `  - "echo pwned > ${PAYLOAD_PATH}"`,
      "on_agent_ready: []",
    ].join("\n");
    await execCapture(running.container, ["sh", "-c", `cat > /app/berth.yml <<'BERTH_EOF'\n${payloadManifest}\nBERTH_EOF`]);
    // Deleting the install marker is part of the chain REMEDIATION 1.6
    // describes, and leaving it out would make this a much weaker test: under
    // the old code the marker is what made a *second* boot skip on_install,
    // so an attack that didn't remove it would fail for a reason that has
    // nothing to do with the fix. Today there is no marker and this is a
    // no-op — which is the point.
    await execCapture(running.container, ["rm", "-f", "/app/.berth/installed"]);
    // Removed so its reappearance can gate the assertion below. The capability
    // policy is generated *after* the lifecycle step in entrypoint.sh, in both
    // the old and new orderings, so "the policy is back" means "whatever this
    // boot was going to run before it, it has already run."
    await execCapture(running.container, ["rm", "-f", "/app/.berth/capability-policy.json"]);
    const rewritten = await execCapture(running.container, ["cat", "/app/berth.yml"]);
    check("the manifest rewrite landed", rewritten.includes(PAYLOAD_PATH), "could not stage the attack at all");

    console.log("  restarting...");
    await restartContainer(running.container);

    // container.restart() resolves when Docker has started the container, not
    // when entrypoint.sh has finished — and this is a *negative* assertion, so
    // reading too early is the difference between a real test and one that
    // always passes. It did always pass, before this wait was added: the
    // negative control ran the old boot-time code and still reported no
    // payload, while doing the same thing by hand produced one.
    const booted = await waitFor(
      async () => (await fileContent(running.container, "/app/.berth/capability-policy.json")) !== ABSENT,
      60000,
    );
    check("the container finished booting after the restart", booted, "capability policy never reappeared — the assertion below would be vacuous");

    const payload = await fileContent(running.container, PAYLOAD_PATH);
    check(
      "the rewritten on_install did not execute on restart",
      payload === ABSENT,
      `${PAYLOAD_PATH} exists — a manifest write plus a restart is still root code execution`,
    );

    console.log("\n--- Test 4: the app itself cannot write where its on_install could ---");
    const enforced = !(await execCapture(running.container, ["cat", "/proc/self/status"])).includes("NoNewPrivs:\t0");
    const wrote = await execCapture(running.container, [
      "sh",
      "-c",
      `echo x > ${PAYLOAD_PATH}-from-app 2>&1 || echo DENIED`,
    ]);
    // Informational, not asserted: this exec is a root shell that is not a
    // descendant of agent-init, so it carries neither the Landlock domain nor
    // the seccomp filters. It's here to show what the build layer's authority
    // looks like next to the app's, not to prove enforcement — that's
    // capability-enforcement.mjs's job.
    console.log(`  (docker exec write to /etc: ${wrote.includes("DENIED") ? "denied" : "permitted"}; no_new_privs seen: ${enforced})`);
  } finally {
    await stopContainer(running.container).catch(() => {});
  }

  console.log("");
  if (failures.length > 0) {
    console.error(`FAILED: ${failures.length} check(s): ${failures.join(", ")}`);
    process.exit(1);
  }
  console.log("All on_install checks passed.");
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
